class Solution {
    public int minSwaps(int[] order) {
        int[] a = order.clone();
        int n = a.length, swaps = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] != i + 1) {
                int j = i + 1;
                while (a[j] != i + 1) j++;
                int t = a[i]; a[i] = a[j]; a[j] = t;
                swaps++;
            }
        }
        return swaps;
    }
}

