class Solution:
    def minSwaps(self, order: List[int]) -> int:
        n = len(order)
        seen = [False] * n
        cycles = 0
        for i in range(n):
            if seen[i]:
                continue
            cycles += 1
            j = i
            while not seen[j]:
                seen[j] = True
                j = order[j] - 1
        return n - cycles

