class Solution {
    public int minSwaps(int[] order) {
        int n = order.length;
        boolean[] seen = new boolean[n];
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            cycles++;
            for (int j = i; !seen[j]; j = order[j] - 1) {
                seen[j] = true;
            }
        }
        return n - cycles;
    }
}

